/** Corpo curado da sinastria para um par de planetas + tom. null se não houver (cai no composer). */
export function synastryPairBody(a: string, b: string, tone: string, lang: string): string | null {
  const key = [String(a || '').toLowerCase(), String(b || '').toLowerCase()].sort().join('+')
  const entry = PAIRS[key]
  const t = (tone === 'harmonioso' || tone === 'tenso' || tone === 'neutro') ? tone as Tone : 'neutro'
  const r = entry?.[t]
  return r ? (r[L(lang)] || r['pt-BR']) : null
}
